"use client";
import Image from "next/image";
import { useTranslations } from "next-intl";
import { useEffect, useState } from "react";

// Generated by scripts/render-hero-video.py (seamless 10s loop)
const HERO_POSTER = "/images/hero-particles-poster.jpg";
// Keep the particle river (right side of the frame) in view on portrait screens
const HERO_MEDIA_POSITION = "object-cover object-[72%_50%]";

type NavigatorWithConnection = Navigator & {
  connection?: { saveData?: boolean };
};

/** Video only after mount, and never for reduced-motion or Save-Data users (poster stays). */
function useShouldPlayHeroVideo() {
  const [shouldPlay, setShouldPlay] = useState(false);

  useEffect(() => {
    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    const isSaveData =
      (navigator as NavigatorWithConnection).connection?.saveData === true;
    setShouldPlay(!prefersReducedMotion && !isSaveData);
  }, []);

  return shouldPlay;
}

export default function AreaHero() {
  const t = useTranslations("hero");
  const shouldPlayVideo = useShouldPlayHeroVideo();

  return (
    <section className="relative h-screen min-h-[600px] flex items-center overflow-hidden bg-[var(--dark-bg)]">
      <div aria-hidden="true" className="absolute inset-0">
        <Image
          src={HERO_POSTER}
          alt=""
          fill
          priority
          sizes="100vw"
          className={HERO_MEDIA_POSITION}
        />
        {shouldPlayVideo && (
          <video
            className={`absolute inset-0 h-full w-full ${HERO_MEDIA_POSITION}`}
            autoPlay
            muted
            loop
            playsInline
            poster={HERO_POSTER}
          >
            <source src="/videos/hero-particles.webm" type="video/webm" />
            <source src="/videos/hero-particles.mp4" type="video/mp4" />
          </video>
        )}
        {/* Keeps the copy legible where the particles sit behind it (narrow screens) */}
        <div className="absolute inset-0 bg-gradient-to-r from-[var(--dark-bg)]/80 via-[var(--dark-bg)]/30 to-transparent" />
      </div>

      {/* Content */}
      <div className="relative z-10 w-full max-w-7xl mx-auto px-4 md:px-8 lg:px-16 text-white">
        <div className="inline-block mb-8 fade-in">
          <span className="text-amber-400 text-sm md:text-base font-medium tracking-[0.25em] uppercase">
            webhani
          </span>
        </div>
        <h1
          className="text-4xl md:text-6xl lg:text-7xl font-medium mb-8 fade-in leading-[1.2] tracking-tight"
          style={{ animationDelay: "0.15s" }}
        >
          {t("title")
            .split("\n")
            .map((line, i, arr) => (
              <span key={i}>
                {line}
                {i < arr.length - 1 && <br />}
              </span>
            ))}
        </h1>
        <p
          className="text-lg md:text-xl mb-12 fade-in text-white/60 max-w-2xl leading-relaxed"
          style={{ animationDelay: "0.3s" }}
        >
          {t("subtitle")
            .split("\n")
            .map((line, i, arr) => (
              <span key={i}>
                {line}
                {i < arr.length - 1 && <br />}
              </span>
            ))}
        </p>
        <div className="fade-in" style={{ animationDelay: "0.45s" }}>
          <button
            type="button"
            onClick={() => {
              document.getElementById("contact")?.scrollIntoView({
                behavior: "smooth",
              });
            }}
            className="group relative inline-flex items-center gap-2 bg-amber-500 hover:bg-amber-400 text-gray-900 font-medium
            py-4 px-10 rounded-full transition-colors duration-300"
          >
            {t("button")}
            <svg
              className="w-4 h-4 transition-transform duration-300 group-hover:translate-x-1"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M17 8l4 4m0 0l-4 4m4-4H3"
              />
            </svg>
          </button>
        </div>
      </div>

      {/* Scroll indicator */}
      <div className="absolute bottom-10 left-1/2 transform -translate-x-1/2 flex flex-col items-center gap-2">
        <span className="text-white/50 text-xs tracking-[0.2em] uppercase">
          Scroll
        </span>
        <div className="w-px h-8 bg-gradient-to-b from-white/50 to-transparent animate-pulse" />
      </div>
    </section>
  );
}
